(root/'questions_all.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
out=Path('/workspace/shared/timepalette-belize')
out.mkdir(parents=True,exist_ok=True)
for i in range(0,len(questions),5):
    batch={'version':manifest['version'],'questions':questions[i:i+5]}
    with ZipFile(out/f'Belize_{i//5+1:02d}.zip','w',ZIP_DEFLATED) as z:
        z.writestr('questions.json',json.dumps(batch,ensure_ascii=False,indent=2))
print('Created',len(questions),'questions in',(len(questions)+4)//5,'batches')
